import { total as tM } from './cart-master.mjs';
import { total as tA } from './cart-A.mjs';
import { invoice as invM } from './invoice-master.mjs';
import { total as tB } from '../../src/cart.js';
import { invoice as invB } from '../../src/invoice.js';

const mk = (n, prices) => Array.from({ length: n }, (_, i) => ({ price: prices[i % prices.length], qty: 1 }));
// exact half-up reference using BigInt: subtotal * (den-num)/den * (95/100 if bulk)
function exact(subtotal, rateNum, rateDen, bulk) {
  let num = BigInt(subtotal) * BigInt(rateDen - rateNum) * (bulk ? 95n : 100n);
  let den = BigInt(rateDen) * 100n;
  return Number((2n * num + den) / (2n * den)); // floor(x + 1/2), x >= 0
}

console.log('--- A acceptance criteria');
console.log('AC1 1 line 1000 @0.1 ->', tA([{ price: 1000, qty: 1 }], 0.1), '(spec 900; master', tM([{ price: 1000, qty: 1 }], 0.1), ')');
for (let n = 1; n <= 9; n++) { const v = tA(mk(n, [1000]).map(x => ({ price: 1000 / n, qty: 1 })), 0.1); if (v !== 900) console.log('AC1 MISMATCH n=', n, v); }
console.log('AC2 10 lines 10000 @0.1 ->', tA(mk(10, [1000]), 0.1), '(spec 8550; master', tM(mk(10, [1000]), 0.1), ')');
console.log('AC2 11 lines 11000 @0.1 ->', tA(mk(11, [1000]), 0.1), '(exact', exact(11000, 1, 10, true), ')');

console.log('--- A vs master at rate 0 (omitted, 0, -0, undefined)');
let diffs = 0, n0 = 0;
let seed = 12345; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
// exhaustive on subtotal for single-line and 10-line carts
for (let s = 0; s <= 300000; s++) {
  for (const items of [[{ price: s, qty: 1 }], [{ price: s, qty: 1 }, ...mk(9, [0])]]) {
    for (const args of [[], [0], [-0], [undefined]]) { n0++; if (tM(items, ...args) !== tA(items, ...args)) { diffs++; if (diffs < 5) console.log('DIFF', s, items.length, args); } }
  }
}
// random carts incl. fractional prices / big numbers
for (let i = 0; i < 300000; i++) {
  const n = Math.floor(rnd() * 25);
  const items = Array.from({ length: n }, () => ({ price: rnd() < 0.2 ? Math.round(rnd() * 1e9) / 100 : Math.floor(rnd() * 100000), qty: 1 + Math.floor(rnd() * 20) }));
  n0++; if (!Object.is(tM(items), tA(items)) || !Object.is(tM(items, 0), tA(items, 0))) { diffs++; if (diffs < 5) console.log('DIFF', JSON.stringify(items)); }
}
console.log('rate-0 comparisons:', n0, 'differences:', diffs);

console.log('--- A/B vs exact half-up arithmetic (integer subtotals)');
for (const [label, fn, bulkAt] of [['A', tA, 10], ['B', tB, 2]]) {
  for (const [num, den] of [[0, 1], [1, 10], [5, 100], [15, 100], [2, 10], [25, 100], [3, 10], [1, 3].slice(0, 2)]) {
    if (den === 3) continue;
    const rate = num / den; let bad = 0, first = null, cnt = 0;
    for (let s = 0; s <= 200000; s++) for (const n of [1, bulkAt]) {
      const items = [{ price: s, qty: 1 }, ...mk(n - 1, [0])]; cnt++;
      const got = fn(items, rate), want = exact(s, num, den, n >= bulkAt);
      if (got !== want) { bad++; first ??= { s, n, got, want }; }
    }
    console.log(label, 'rate', rate, 'cases', cnt, 'mismatch', bad, first ? JSON.stringify(first) : '');
  }
}

console.log('--- B: cart threshold by line count (price 1000 each, rate 0 and 0.1)');
for (const n of [0, 1, 2, 3, 9, 10, 11]) console.log(n, 'lines:', tB(mk(n, [1000])), tB(mk(n, [1000]), 0.1), ' A:', tA(mk(n, [1000])), tA(mk(n, [1000]), 0.1));
console.log('B 2 lines 250 ->', tB([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), ' raw', 250 * 0.95, 250 * (1 - 0) * (1 - 0.05));
console.log('B qty does not count as lines: 1 line qty 50 ->', tB([{ price: 10, qty: 50 }]));

console.log('--- B: invoice vs master invoice');
let idiff = 0, ic = 0;
for (let n = 0; n <= 30; n++) for (let s = 0; s <= 20000; s++) { const items = [{ price: s, qty: 1 }, ...mk(Math.max(n - 1, 0), [7])].slice(0, n); ic++; if (invM('c', items).due !== invB('c', items).due) { idiff++; if (idiff < 5) console.log('INV DIFF', n, s, invM('c', items).due, invB('c', items).due); } }
for (let i = 0; i < 200000; i++) { const n = Math.floor(rnd() * 25); const items = Array.from({ length: n }, () => ({ price: Math.floor(rnd() * 100000), qty: 1 + Math.floor(rnd() * 20) })); ic++; if (invM('c', items).due !== invB('c', items).due) { idiff++; if (idiff < 5) console.log('INV DIFF', JSON.stringify(items)); } }
console.log('invoice comparisons:', ic, 'differences:', idiff);
for (const n of [1, 2, 3, 9, 10, 11]) console.log('invoice', n, 'lines x1000:', invB('c', mk(n, [1000])).due, 'master:', invM('c', mk(n, [1000])).due);
console.log('invoice shape', JSON.stringify(invB('acme', mk(2, [100]))), JSON.stringify(invM('acme', mk(2, [100]))));

