import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200); // a single line: no bulk discount
});

test('bulk discount starts at 2 lines', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 238); // 250 * 0.95 = 237.5
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// Issue #12: the customer's discount is applied once, then the bulk discount once.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (single line, no bulk discount)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1,000 - 10%
});

test('customer discount, then bulk discount at 2 lines', () => {
  assert.equal(total(lines(2, 500), 0.1), 855); // 1,000 - 10% = 900, then - 5%
});

test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550); // 10,000 - 10% = 9,000, then - 5%
});

